// Turns a failed execution into one readable record, kept in this
// workflow's execution list. Add an email or chat node after this one to be
// alerted as well.
const { workflow = {}, execution = {}, trigger = {} } = $input.first().json;

const failure = {
  workflow: workflow.name ?? 'unknown workflow',
  node: execution.lastNodeExecuted ?? trigger.error?.node?.name ?? 'unknown node',
  message: execution.error?.message ?? trigger.error?.message ?? 'unknown error',
  executionId: execution.id ?? null,
  executionUrl: execution.url ?? null,
  failedAt: new Date().toISOString(),
};

return [{ json: failure }];
